{
  "story": "Follow a simplified, healthy resting heartbeat. Atria receive blood; ventricles pump it. Both sides are synchronized here. Compare filling and squeezing through pressure and valve states. Watch blood leave toward the lungs and body instead of returning to the atria. Use Previous and Next; Reset restarts.",
  "aha": {
    "stateId": "ejection",
    "observation": "Squeezing ventricles raise pressure, closing inlet valves and opening outlet valves so blood moves toward the lungs and body."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "heartbeat-rail",
      "kind": "step-rail",
      "presentation": "Place below the explanation and above the experiment. Show ordered states, completed states, and the active state without clock markings.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "circulation-picture",
      "kind": "fixed-picture",
      "presentation": "Use the fixed cycle arrangement with paired heart pathways. Keep every named region visible and stationary. Arrows indicate anatomical routes, not continuous flow. Highlight only the bound active regions. Use readable labels without animated particles, anatomical scaling, or changing chamber geometry.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "phase-evidence",
      "kind": "value-readout",
      "presentation": "Show four compact rows beneath the picture. Compare pressures within each side, never across sides. Comparisons are qualitative, so units and rounding do not apply. Volume describes change during the selected phase, not a numerical measurement.",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "active-status",
      "kind": "active-callout",
      "presentation": "Anchor beside the named target without covering labels. Use the bound sentence as the status line and the reason as its explanation.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    }
  ],
  "controls": [
    {
      "id": "heartbeat-state",
      "kind": "index",
      "items": "variant.states",
      "label": "Heartbeat state",
      "presentation": "Use Previous and Next with one-state increments, defaulting to the first state. Bounds are the first and last states, without wrapping. Retain both names when boundary buttons are disabled. Every state persists until learner action, including ejection. Reference captures show ejection. Balanced parameter-control budget: zero; navigation and Reset are separate. Fixed assumptions are healthy valves, resting circulation, and simplified synchronization between sides. Provide keyboard operation, visible focus, and accessible names matching visible labels."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all fixed defaults. Provide keyboard operation, visible focus, and the accessible name Reset."
    }
  ],
  "data": {
    "variants": [
