            "values": ["Left inlet"]
          },
          {
            "id": "left-ventricle",
            "label": "Left ventricle",
            "values": ["Pumping chamber"]
          },
          {
            "id": "aortic",
            "label": "Aortic valve",
            "values": ["Left outlet"]
          }
        ],
        "links": [
